eval("/**\n *  @file       keystoreFile.js\n *              Modal providing a way to upload a keystore file and cache it (on request) in local/session storage.\n * \n *  @author     KC Erb           - kcerb@kingsds.network\n *  @author     Nazila Kharazian - nazila@kingsds.network\n *  @date       Apr 2020\n */\nconst utils = __webpack_require__(/*! ./utils */ \"./src/dcp-client/client-modal/utils.js\");\nconst { confirm } = __webpack_require__(/*! ./confirm */ \"./src/dcp-client/client-modal/confirm.js\");\nconst passwordModule = __webpack_require__(/*! ./passwordEntry */ \"./src/dcp-client/client-modal/passwordEntry.js\");\n\nexports.config = {\n  id: 'dcp-modal-keystore-file',\n  required: ['dcp-modal-keystore-file-form', 'dcp-modal-keystore-file-prompt', 'dcp-modal-keystore-file-input'],\n  path: \"./templates/keystore-file-modal.html\",\n  eagerLoad: [passwordModule.config]\n};\n\n/**\n * @param {Object} options From `wallet.get_internal`\n * @param {string} options.name - The name of the keystore type (wallet.get => 'default' and wallet.getId => 'id').\n * @param {string} options.contextId - An optional, user-defined identifier used for caching keystores.\n *                                     See `job.contextId` in the compute-api spec.\n * @param {string} options.jobName - A user-defined job property provided to identify this job.\n * @param {string} options.msg - Optional string denoting the purpose for fetching the keystore\n * @param {function} [onClose] Override default onClose behavior. An instance of `modal` is handed to the function.\n * @throws If modal is closed without the form being submitted (submitting the form closes the modal).\n * @returns {string} contents of Keystore file\n * @memberof module:dcp/client-modal\n * @access public\n * @async\n * @alias getKeystoreFile\n */\nexports.keystoreFile = async function (options, onClose=null) {\n  const storageKey = `dcp-keystore-${options.name}-${options.contextId}`;\n  \n  let jobName = options.jobName;\n  if (jobName) {\n    jobName = `\"${jobName}\"`;\n  } else {\n    jobName = 'this job';\n  }\n\n  let keystoreType;\n  switch (options.name) {\n    case 'id':\n      keystoreType = \"DCP identity\";\n      break;\n    case 'default':\n      keystoreType = \"DCP Bank Account\";\n    default:\n      keystoreType = options.name;\n      break;\n  };\n\n  let keystoreMsg = options.msg;\n\n  let keystoreFile = await getKeystoreFromStorage(storageKey, jobName, onClose);\n  if (!keystoreFile) {\n    keystoreFile = await getKeystoreFromUser(keystoreType, jobName, storageKey, onClose, keystoreMsg);\n  }\n\n  return keystoreFile;\n};\n\n/**\n * Alert user that a key from storage will be used, give them a chance to ditch it.\n * @param {string} storageKey key in local or session storage where the file is stored\n * @param {string} jobName helps user know which key is retrieved from storage\n * @returns {string} contents of Keystore file\n */\nasync function getKeystoreFromStorage (storageKey, jobName) {\n  let keystoreFile = sessionStorage.getItem(storageKey);\n  if (keystoreFile) return keystoreFile;\n  \n  keystoreFile = localStorage.getItem(storageKey);\n  if (keystoreFile) {\n    let ks = JSON.parse(keystoreFile);\n    let label = ks.label || ks.address;\n    let prompt;\n    // alert is not necessarily for a job, specify jobname only if there is an actual job\n    if(jobName)\n      prompt = `You have keystore \"${label}\" saved for ${jobName}. Do you want to use it?`;\n    else\n      prompt = `You have keystore \"${label}\". Do you want to use it?`;\n    let opts = { positive: \"Yes\", negative: \"No\", title: 'Keystore File' };\n    let confirmation = await confirm(prompt, opts);\n    if (confirmation) {\n      sessionStorage.setItem(storageKey, keystoreFile)\n      return keystoreFile;\n    }\n    localStorage.removeItem(storageKey);\n    return false;\n  };\n};\n\n/**\n * Bring up file prompt modal in browser, give user option to save the file locally for easier access.\n * @param {string} keystoreType Help user know whether to upload an identity or bank or whatever keystore.\n * @param {string} jobName Help user identify the job this key will be used on.\n * @param {string} storageKey Store the key in local/session storage under this key.\n * @param {string} msg Custom message for the modal that specifies the purpose for providing a keystore\n * @throws If modal is closed without the form being submitted (submitting the form closes the modal).\n */\nasync function getKeystoreFromUser (keystoreType, jobName, storageKey, onClose, msg) {\n  const [elements, formPromise] = await utils.initModal(exports.config, onClose);\n  const [modal, form, prompt, fileInput] = elements;\n  \n  // default modal text that explains what a keystore is for.\n  prompt.innerHTML = 'This application is<br> requesting a DCP keystore';\n  if (msg)\n  {\n    prompt.innerHTML = msg;\n  }\n  \n  document.getElementById('dcp-modal-keystore-file-upload-button').onclick = function (e) {\n    fileInput.click();\n  }\n\n  fileInput.focus();\n  fileInput.onchange = async function () {\n    let files = fileInput.files;\n    if (!files || files.length === 0) return;\n    const keystoreFile = await fileToString(files[0]);\n    try {\n      JSON.parse(keystoreFile);\n    } catch (error) {\n      fileInput.setCustomValidity(\"File could not be parsed as JSON. Please upload a JSON keystore file.\");\n      return;\n    };\n    fileInput.setCustomValidity(\"\");\n    document.getElementById('dcp-modal-keystore-file-submit').click();\n  };\n\n  await formPromise;\n  let files = fileInput.files;\n  const keystoreFile = await fileToString(files[0]);\n  \n  utils.MicroModal.close(modal.id);\n  return keystoreFile;\n};\n\n/**\n * Helper for reading in an uploaded file and returning the stringified version.  \n * @param {File} inputFile Element of FileList\n * @returns {string} Contents of file.\n */\nconst fileToString = function (inputFile) {\n  return new Promise((resolve, reject) => {\n    const fileReader = new FileReader();\n\n    fileReader.onerror = function () {\n      reject(new DOMException('Problem parsing input file.'));\n    };\n\n    fileReader.onload = function () {\n      resolve(this.result);\n    };\n\n    fileReader.readAsText(inputFile);\n  });\n};\n\n\n//# sourceURL=webpack://dcp/./src/dcp-client/client-modal/keystoreFile.js?");

