eval("/**\n * @file dcp/src/dcp-client/worker/supervisor2/module-cache.js\n *\n * A cache for modules.\n *\n * @author Matthew Palma, mpalma@kingsds.network\n *         Paul, paul@distributive.network\n * @date May 2019\n *       June 2022, April 2023\n * @module module-cache\n * @copyright Copyright (c) 2018-2023, Distributive Corp. All Rights Reserved\n */\n\nconst debugging = (__webpack_require__(/*! dcp/debugging */ \"./src/debugging.js\").scope)('worker');\nconst { EventEmitter } = __webpack_require__(/*! dcp/common/dcp-events */ \"./src/common/dcp-events/index.js\");\n\n/** @typedef {import('./index').Supervisor} Supervisor */\n\nclass ModuleCache extends EventEmitter\n{\n  /**\n   * @constructor\n   * @param {Supervisor} supervisor\n   */\n  constructor (supervisor)\n  {\n    super('ModuleCache')\n    /** @type {Supervisor} */\n    this.supervisor = supervisor;\n    this.cache = {};  // Modules keyed by module group.\n  }\n\n  /**\n   * Returns an object listing what jobs and modules are currently cached.\n   * @returns {string} - in the form: moduleGroup1: [ job1 ], moduleGroup2: [ job1, job2 ]...\n   */\n  get cacheDescription ()\n  {\n    const desc = {};\n    for (const [ id, moduleJobs ] of Object.entries(this.cache))\n      desc[id] = moduleJobs.jobs;\n    return JSON.stringify(desc);\n  }\n\n  /**\n   * Attempts to look up an item from the cache.\n   * @param {string} id  - the items module group name\n   * @param {string} job - the job calling fetch\n   * @returns {any} The value of the stored item or undefined if nothing is found\n   */\n  fetch(id, job)\n  {\n    const moduleJobs = this.cache[id];\n    if (!moduleJobs) return moduleJobs;\n    if (moduleJobs.jobs.indexOf(job) === -1 )\n      moduleJobs.jobs.push(job);\n    return moduleJobs.module;\n  }\n\n  /**\n   * Stores a fetched value for one of the caches.\n   * @param {string} id  - the items identifier module group name\n   * @param {string} job - the job calling fetch\n   * @param {any} value  - the item to store\n   * @returns {any} - @value passed in\n   */\n  store (id, job, value)\n  {\n    if (!this.cache[id]) this.cache[id] = { module: value, jobs: [ job ] };\n    else if (this.cache[id].jobs.indexOf(job) === -1) this.cache[id].jobs.push(job);\n    return value\n  }\n    \n  /**\n   * Removes a job reference from a module cache.\n   * When there are no jobs left, the module cache entry is destroyed.\n   * @param {string} job - the job to be removed.\n   */\n  removeJob (job)\n  {\n    for (const [ id, moduleJobs ] of Object.entries(this.cache))\n    {\n      moduleJobs.jobs = moduleJobs.jobs.filter(_job => _job !== job);\n      if (moduleJobs.jobs.length < 1) delete this.cache[id];\n    }\n  }\n\n  /**\n   * Attempts to fetch a module group from the cache and\n   * if it's not found it attempts to fetch then store\n   * the module group from the package manager.\n   *\n   * @param {array} modulesArray - the array of modules requested \n   *        - (when stringified it's the identifier of the module group)\n   *\n   * @returns {Promise<object>} - the module group\n   * @throws when the module group can not be fetched\n   */\n  async fetchModule(modulesArray, job)\n  {\n    const cacheKey = JSON.stringify(modulesArray);\n    let modules = this.fetch(cacheKey, job);\n    if (modules)\n    {\n      debugging() && console.debug('FetchModule: Cache hit', { cacheKey, job });\n      return modules;\n    }\n\n    if (!this.supervisor.dcp4.packageManager\n      || this.supervisor.dcp4.packageManager.state.in(['closed', 'close-wait', 'closing']))\n      throw new Error(`fetchModule: Package manager connection is closed`);\n    debugging() && console.debug('FetchModule for modules name(s)', cacheKey);\n\n    const resp = await this.supervisor.dcp4.packageManager.send('fetchModule', { modules: modulesArray });\n\n    if (!resp.success)\n    {\n      const errorMsg = `FetchModule: Calling the package manager failed for module name(s) ${cacheKey}`;\n      if (resp.payload)\n      {\n        debugging() && console.debug(errorMsg, resp.payload);\n        throw resp.payload;\n      }\n      debugging() && console.debug(errorMsg);\n      throw new Error(errorMsg);\n    }\n\n    modules = await resp.payload; /** @todo XXXpfr This seems wrong. */\n    return this.store(cacheKey, job, modules);\n  }\n}\nexports.ModuleCache = ModuleCache;\n\n\n//# sourceURL=webpack://dcp/./src/dcp-client/worker/supervisor2/module-cache.js?");

