eval("/**\n * @file dcp/src/dcp-client/worker/supervisor2/options.js\n *\n * A support class for Supervisor2.\n * It is for managing Supervisor options and config access.\n *\n * @author Paul, paul@distributive.network\n * @date Feb-April 2023,\n * @module options\n * @copyright Copyright (c) 2018-2023, Distributive Corp. All Rights Reserved\n */\n/* global dcpConfig */ // eslint-disable-line no-redeclare\n// @ts-check\n\n\nconst { assert } = __webpack_require__(/*! dcp/common/dcp-assert */ \"./src/common/dcp-assert.js\");\nconst DCP_ENV = __webpack_require__(/*! dcp/common/dcp-env */ \"./src/common/dcp-env.js\");\nconst { localStorage } = __webpack_require__(/*! dcp/common/dcp-localstorage */ \"./src/common/dcp-localstorage.js\");\nconst { requireNative } = __webpack_require__(/*! dcp/dcp-client/webpack-native-bridge */ \"./src/dcp-client/webpack-native-bridge.js\");\nconst { Address } = __webpack_require__(/*! dcp/dcp-client/wallet/eth */ \"./src/dcp-client/wallet/eth.js\");\nconst { leafMerge } = __webpack_require__(/*! dcp/utils/obj-merge */ \"./src/utils/obj-merge.js\");\nconst constants = __webpack_require__(/*! dcp/common/scheduler-constants */ \"./src/common/scheduler-constants.js\");\nconst { ms, generateOpaqueId } = __webpack_require__(/*! dcp/utils */ \"./src/utils/index.js\");\n\nconst { Config } = __webpack_require__(/*! ./config */ \"./src/dcp-client/worker/supervisor2/config.js\");\nconst { selectiveDebug, selectiveDebug2 } = __webpack_require__(/*! ./common */ \"./src/dcp-client/worker/supervisor2/common.js\");\n\n/** @typedef {import('./index').Supervisor} Supervisor */\n/** @typedef {import('dcp/dcp-client/wallet/eth').Address} Address */\n/** @typedef {import('dcp/utils/jsdoc-types').SupervisorOptions} SupervisorOptions */\n/** @typedef {string} opaqueId */ // 22 character base64 string\n\n/**\n * It is important that options and config properties can be changed dynamically\n * and have the new values reflected in supervisor/worker operations.\n */\nclass Options extends Config\n{\n  /** Private class fields */\n  /** @type {opaqueId} */\n  #workerId;\n  /** @type {number} */\n  #targetTaskDuration;\n\n  /**\n   * @constructor\n   * @param {SupervisorOptions} options - options for starting worker; generally dcpConfig.worker.\n   * @param {Worker} worker     worker  - EventEmitter which we use for warning and error event emits.\n   */\n  constructor(options, worker)\n  {\n    super();\n    assert(options === worker.workerOptions);\n    \n    /**\n     * @type {SupervisorOptions} \n     * This is a reference to the configuration object supplied by the API consumer, and is\n     * effectively part of the Worker API. Changes to this object are intended to affect the\n     * running supervisor eventually.\n     */\n    this.options = options;\n\n    selectiveDebug2() && console.debug('Sup2:hardware, default core density, cores:', \n                                       options.hardware, options.defaultCoreDensity, options.cores);\n  }\n\n  //\n  // The SupervisorOptions accessors\n  //\n\n  /** @type {{ cpu: number, gpu: number }} */\n  get cores () { return this.options.cores; }\n  /** @type {{ cpu: number, gpu: number }} */\n  set cores (newCores)\n  {\n    this.options.cores = newCores;\n  }\n  /** @type {Address} */\n  get paymentAddress ()\n  {\n    if (!(this.options.paymentAddress instanceof Address))\n      throw new Error(`options.paymentAddress ${JSON.stringify(this.options.paymentAddress)} must be an instance of Address`);\n    return this.options.paymentAddress;\n  }\n  /** @type {Address} */\n  set paymentAddress (addr) { this.options.paymentAddress = addr; }\n  /** @type {string[]} */\n  get jobAddresses () { return this.options.jobAddresses ?? []; }\n  /** @type {any[]} */\n  get computeGroups () { return this.options.computeGroups; }\n  /** @type {boolean} */\n  get leavePublicGroup () { return this.options.leavePublicGroup; }\n  /** @type {*} */\n  get schedulerConfig () { return leafMerge(dcpConfig.scheduler, this.options.schedulerConfig); }\n  /** @type {boolean} */\n  get allowConsoleAccess () { return this.options.allowConsoleAccess; }\n  /** @type {*} */\n  get sandboxOptions () { return this.options.sandboxOptions; }\n  /** @type {boolean} */\n  get trustComputeGroupOrigins () { return this.options.trustComputeGroupOrigins; }\n  /** @type {{CPU: number, GPU: number, 'in': number, out: number}} */\n  get minimumWage () { return this.options.minimumWage ?? { CPU: 0, GPU: 0, in: 0, out: 0 }; }\n  /** @type {{ any: string[], fetchData: string[], fetchWorkFunctions: string[], fetchArguments: string[], sendResults: string[] }} */\n  get allowOrigins () { return this.options.allowOrigins; }\n\n  /** @type {number} */\n  get watchdogInterval ()\n  {\n    if (this.options.watchdogInterval)\n      return ms(Number(this.options.watchdogInterval));\n    return ms(Number(dcpConfig.supervisor.tuning.watchdogInterval ?? 7));\n  }\n  /** @type {number} */\n  set watchdogInterval (wdInterval) { this.options.watchdogInterval = wdInterval; }\n  /** @type {opaqueId} */\n  get workerId ()\n  {\n    if (!this.#workerId)\n    {\n      /** @type {opaqueId} */\n      this.#workerId = localStorage.getItem('workerId');\n      if (!this.#workerId || this.#workerId.length !== constants.workerIdLength)\n        this.workerId = generateOpaqueId();\n    }\n    return this.#workerId;\n  }\n  /** @type {opaqueId} */\n  set workerId (newId)\n  {\n    this.#workerId = newId;\n    localStorage.setItem('workerId', this.#workerId);\n  }\n\n  /**\n   * Each task returned by TD.requestTask is this.targetTaskDuration() ms of work.\n   * @returns {number}\n   */\n  get targetTaskDuration () { return ms(this.#targetTaskDuration || 300); }\n  set targetTaskDuration (tTD) { this.#targetTaskDuration = tTD; }\n\n  /**\n   * When # of sandboxes exceeds this level, we more aggressively prune.\n   * @returns {number}\n   */\n  get mustPruneSandboxLevel () { return this.mustPruneMultiplier * this.maxSandboxes; }\n\n  /**\n   * Determine the total number of sandboxes which can be working at once. This number is a\n   * limiter that is independent of workload density, so that we can keep a handle on both\n   * overhead and overall memory consumption inspite of measurement/rounding errors.\n   */\n  get maxSandboxes()\n  {\n    selectiveDebug2() && console.debug('Enter computeMaxBusySandboxes d/c/hw', this.options.defaultCoreDensity, this.options.cores, this.options.hardware);\n\n    // We're making the assumption that machines with more cores can handle extra sandboxes.\n    const multiplier = (k) => {\n      if (k > 15) return this.maxSandboxSlack;\n      return (this.minSandboxSlack * (15 - k) + this.maxSandboxSlack * (k - 1)) / (15 - 1);\n    }\n    const numVCores = this.options.hardware.vCores || this.options.cores.cpu;\n    return Math.max(Math.ceil(this.cores.cpu + multiplier(numVCores) * numVCores), this.options.cores.cpu);\n  }\n  /**\n   * Gets the logical and physical number of cores and also the total number of sandboxes the worker is allowed to run.\n   * @returns {{ worker: opaqueId, lCores: number, pCores: number, sandbox: number}}\n   */\n  getStatisticsCPU ()\n  {\n    if (DCP_ENV.isBrowserPlatform)\n    {\n      return {\n        worker: this.workerId,\n        lCores: this.options.hardware.vCores || window.navigator.hardwareConcurrency,\n        pCores: window.navigator.hardwareConcurrency,\n        sandbox: this.maxSandboxes,\n      }\n    }\n\n    return {\n      worker: this.workerId,\n      lCores: this.options.hardware.vCores || requireNative('os').cpus().length,\n      pCores: requireNative('physical-cpu-count'),\n      sandbox: this.maxSandboxes,\n    }\n  }\n}\nexports.Options = Options;\n\n\n//# sourceURL=webpack://dcp/./src/dcp-client/worker/supervisor2/options.js?");

